<template><section class="settings-card"><h2>自动化</h2><label class="settings-check"><mdui-switch :checked="props.modelValue.idleDownload.enabled" @change="emit('update:modelValue', { idleDownload: { ...props.modelValue.idleDownload, enabled: ($event.target as HTMLInputElement).checked } })"></mdui-switch>空闲时自动下载</label><label v-if="props.modelValue.idleDownload.enabled">空闲阈值（秒）<mdui-text-field variant="outlined" type="number" min="60" :value="String(props.modelValue.idleDownload.idleAfterSeconds)" @input="emit('update:modelValue', { idleDownload: { ...props.modelValue.idleDownload, idleAfterSeconds: Number(($event.target as HTMLInputElement).value) } })"></mdui-text-field></label><label>完成后动作<mdui-select variant="outlined" :value="props.modelValue.completionAction" @change="emit('update:modelValue', { completionAction: ($event.target as HTMLInputElement).value as DownloadPolicy['completionAction'] })"><mdui-menu-item value="none">无</mdui-menu-item><mdui-menu-item value="pause-all">暂停全部任务</mdui-menu-item><mdui-menu-item value="stop-engine">停止引擎</mdui-menu-item><mdui-menu-item value="suspend">睡眠</mdui-menu-item><mdui-menu-item value="poweroff">关机</mdui-menu-item></mdui-select></label><mdui-button variant="tonal" class="secondary-button" @click="emit('schedules')">管理计划任务</mdui-button></section></template>
